28: int CheckMouseButton(const char * const b, MMMouseButton * const button)
29: {
30: 	if (!button) return -1;
31: 
32: 	if (strcmp(b, "left") == 0)
33: 	{
34: 		*button = LEFT_BUTTON;
35: 	}
36: 	else if (strcmp(b, "right") == 0)
37: 	{
38: 		*button = RIGHT_BUTTON;
39: 	}
40: 	else if (strcmp(b, "middle") == 0)
41: 	{
42: 		*button = CENTER_BUTTON;
43: 	}
44: 	else
45: 	{
46: 		return -2;
47: 	}
48: 
49: 	return 0;
50: }
