478: int GetFlagsFromValue(Napi::Value value, MMKeyFlags* flags) {
479: 	if (!flags) return -1;
480: 
481: 	//Optionally allow an array of flag strings to be passed.
482: 	if (value.IsArray())
483: 	{
484: 		Napi::Array a = value.As<Napi::Array>();
485: 		for (uint32_t i = 0; i < a.Length(); i++)
486: 		{
487: 		  if ((a).Has(i)) {
488:                 Napi::Value v((a).Get(i));
489:                 if (!v.IsString()) return -2;
490: 
491:                 MMKeyFlags f = MOD_NONE;
492:                 const int rv = GetFlagsFromString(v, &f);
493:                 if (rv) return rv;
494: 
495:                 *flags = (MMKeyFlags)(*flags | f);
496: 			}
497: 		}
498: 		return 0;
499: 	}
500: 
501: 	//If it's not an array, it should be a single string value.
502: 	return GetFlagsFromString(value, flags);
503: }
