558: Napi::Value keyToggleWrapper(const Napi::CallbackInfo& info)
559: {
560: 	Napi::Env env = info.Env();
561: 
562: 	MMKeyFlags flags = MOD_NONE;
563: 	MMKeyCode key;
564: 
565: 	bool down;
566: 	const char *k;
567: 
568: 	//Get arguments from JavaScript.
569: 	std::string kstr = info[0].As<Napi::String>();
570: 
571: 	//Convert arguments to chars.
572: 	k = kstr.c_str();
573: 
574: 	//Check and confirm number of arguments.
575: 	switch (info.Length())
576: 	{
577: 		case 3:
578: 			//Get key modifier.
579: 			switch (GetFlagsFromValue(info[2], &flags))
580: 			{
581: 				case -1:
582: 					Napi::Error::New(env, "Null pointer in key flag.").ThrowAsJavaScriptException();
583: return env.Null();
584: 					break;
585: 				case -2:
586: 					Napi::Error::New(env, "Invalid key flag specified.").ThrowAsJavaScriptException();
587: return env.Null();
588: 					break;
589: 			}
590: 			break;
591: 		case 2:
592: 			break;
593: 		default:
594: 			Napi::Error::New(env, "Invalid number of arguments.").ThrowAsJavaScriptException();
595: return env.Null();
596: 	}
597: 
598: 	//Get down value if provided.
599: 	if (info.Length() > 1)
600: 	{
601: 		const char *d;
602: 
603: 		std::string dstr = info[1].As<Napi::String>();
604: 		d = dstr.c_str();
605: 
606: 		if (strcmp(d, "down") == 0)
607: 		{
608: 			down = true;
609: 		}
610: 		else if (strcmp(d, "up") == 0)
611: 		{
612: 			down = false;
613: 		}
614: 		else
615: 		{
616: 			Napi::Error::New(env, "Invalid key state specified.").ThrowAsJavaScriptException();
617: return env.Null();
618: 		}
619: 	}
620: 
621: 	//Get the actual key.
622: 	switch(CheckKeyCodes(k, &key))
623: 	{
624: 		case -1:
625: 			Napi::Error::New(env, "Null pointer in key code.").ThrowAsJavaScriptException();
626: return env.Null();
627: 			break;
628: 		case -2:
629: 			Napi::Error::New(env, "Invalid key code specified.").ThrowAsJavaScriptException();
630: return env.Null();
631: 			break;
632: 		default:
633: 			toggleKeyCode(key, down, flags);
634: 			microsleep(keyboardDelay);
635: 	}
636: 
637: 	return Napi::Number::New(env, 1);
