112: void toggleKeyCode(MMKeyCode code, const bool down, MMKeyFlags flags)
113: {
114: #if defined(IS_MACOSX)
115: 	/* The media keys all have 1000 added to them to help us detect them. */
116: 	if (code >= 1000) {
117: 		code = code - 1000; /* Get the real keycode. */
118: 		NXEventData   event;
119: 		kern_return_t kr;
120: 		IOGPoint loc = { 0, 0 };
121: 		UInt32 evtInfo = code << 16 | (down?NX_KEYDOWN:NX_KEYUP) << 8;
122: 		bzero(&event, sizeof(NXEventData));
123: 		event.compound.subType = NX_SUBTYPE_AUX_CONTROL_BUTTONS;
124: 		event.compound.misc.L[0] = evtInfo;
125: 		kr = IOHIDPostEvent( _getAuxiliaryKeyDriver(), NX_SYSDEFINED, loc, &event, kNXEventDataVersion, 0, FALSE );
126: 		assert( KERN_SUCCESS == kr );
127: 	} else {
128: 		CGEventRef keyEvent = CGEventCreateKeyboardEvent(NULL,
129: 		                                                 (CGKeyCode)code, down);
130: 		assert(keyEvent != NULL);
131: 
132: 		CGEventSetType(keyEvent, down ? kCGEventKeyDown : kCGEventKeyUp);
133: 		CGEventSetFlags(keyEvent, flags);
134: 		CGEventPost(kCGSessionEventTap, keyEvent);
135: 		CFRelease(keyEvent);
136: 	}
137: #elif defined(IS_WINDOWS)
138: 	const DWORD dwFlags = down ? 0 : KEYEVENTF_KEYUP;
139: 
140: 	if (down) {
141: 		/* Parse modifier keys. */
142: 		if (flags & MOD_META) WIN32_KEY_EVENT_WAIT(K_META, dwFlags);
143: 		if (flags & MOD_ALT) WIN32_KEY_EVENT_WAIT(K_ALT, dwFlags);
144: 		if (flags & MOD_CONTROL) WIN32_KEY_EVENT_WAIT(K_CONTROL, dwFlags);
145: 		if (flags & MOD_SHIFT) WIN32_KEY_EVENT_WAIT(K_SHIFT, dwFlags);
146: 
147: 		WIN32_KEY_EVENT_WAIT(code, dwFlags);
148: 	} else {
149: 		/* Reverse order for key up */
150: 		WIN32_KEY_EVENT_WAIT(code, dwFlags);
151: 
152: 		/* Parse modifier keys. */
153: 		if (flags & MOD_META) win32KeyEvent(K_META, dwFlags);
154: 		if (flags & MOD_ALT) win32KeyEvent(K_ALT, dwFlags);
155: 		if (flags & MOD_CONTROL) win32KeyEvent(K_CONTROL, dwFlags);
156: 		if (flags & MOD_SHIFT) win32KeyEvent(K_SHIFT, dwFlags);
157: 	}
158: #elif defined(USE_X11)
159: 	Display *display = XGetMainDisplay();
160: 	const Bool is_press = down ? True : False; /* Just to be safe. */
161: 
162: 	if (down) {
163: 		/* Parse modifier keys. */
164: 		if (flags & MOD_META) X_KEY_EVENT_WAIT(display, K_META, is_press);
165: 		if (flags & MOD_ALT) X_KEY_EVENT_WAIT(display, K_ALT, is_press);
166: 		if (flags & MOD_CONTROL) X_KEY_EVENT_WAIT(display, K_CONTROL, is_press);
167: 		if (flags & MOD_SHIFT) X_KEY_EVENT_WAIT(display, K_SHIFT, is_press);
168: 
169: 		X_KEY_EVENT_WAIT(display, code, is_press);
