171: 		/* Reverse order for key up */
172: 		X_KEY_EVENT_WAIT(display, code, is_press);
173: 
174: 		/* Parse modifier keys. */
175: 		if (flags & MOD_META) X_KEY_EVENT(display, K_META, is_press);
176: 		if (flags & MOD_ALT) X_KEY_EVENT(display, K_ALT, is_press);
177: 		if (flags & MOD_CONTROL) X_KEY_EVENT(display, K_CONTROL, is_press);
