296: 		c = *str++;
297: 
298: 		// warning, the following utf8 decoder
299: 		// doesn't perform validation
300: 		if (c <= 0x7F) {
301: 			// 0xxxxxxx one byte
302: 			n = c;
303: 		} else if ((c & 0xE0) == 0xC0)  {
304: 			// 110xxxxx two bytes
305: 			c1 = (*str++) & 0x3F;
