310: 			c2 = (*str++) & 0x3F;
311: 			n = ((c & 0x0F) << 12) | (c1 << 6) | c2;
312: 		} else if ((c & 0xF8) == 0xF0) {
313: 			// 11110xxx four bytes
314: 			c1 = (*str++) & 0x3F;
315: 			c2 = (*str++) & 0x3F;
316: 			c3 = (*str++) & 0x3F;
317: 			n = ((c & 0x07) << 18) | (c1 << 12) | (c2 << 6) | c3;
318: 		}
