29: MMBitmapRef newMMBitmapFromPNG(const char *path, MMPNGReadError *err)
30: {
31: 	FILE *fp;
32: 	uint8_t header[8];
33: 	png_struct *png_ptr = NULL;
34: 	png_info *info_ptr = NULL;
35: 	png_byte bit_depth, color_type;
36: 	uint8_t *row, *bitmapData;
37: 	uint8_t bytesPerPixel;
38: 	png_uint_32 width, height, y;
39: 	uint32_t bytewidth;
40: 
41: 	if ((fp = fopen(path, "rb")) == NULL) {
42: 		if (err != NULL) *err = kPNGAccessError;
43: 		return NULL;
44: 	}
45: 
46: 	/* Initialize error code to generic value. */
47: 	if (err != NULL) *err = kPNGGenericError;
48: 
49: 	/* Validate the PNG. */
50: 	if (fread(header, 1, sizeof header, fp) == 0) {
51: 		if (err != NULL) *err = kPNGReadError;
52: 		goto bail;
53: 	} else if (png_sig_cmp(header, 0, sizeof(header)) != 0) {
54: 		if (err != NULL) *err = kPNGInvalidHeaderError;
55: 		goto bail;
56: 	}
57: 
58: 	png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
59: 	if (png_ptr == NULL) goto bail;
60: 
61: 	info_ptr = png_create_info_struct(png_ptr);
62: 	if (info_ptr == NULL) goto bail;
63: 
64: 	/* Set up error handling. */
65: 	if (setjmp(png_jmpbuf(png_ptr))) {
66: 		goto bail;
67: 	}
68: 
69: 	png_init_io(png_ptr, fp);
70: 
71: 	/* Skip past the header. */
72: 	png_set_sig_bytes(png_ptr, sizeof header);
73: 
74: 	png_read_info(png_ptr, info_ptr);
75: 
76: 	/* Convert different image types to common type to be read. */
77: 	bit_depth = png_get_bit_depth(png_ptr, info_ptr);
78: 	color_type = png_get_color_type(png_ptr, info_ptr);
79: 
80: 	/* Convert color palettes to RGB. */
81: 	if (color_type == PNG_COLOR_TYPE_PALETTE) {
82: 		png_set_palette_to_rgb(png_ptr);
83: 	}
84: 
85: 	/* Convert PNG to bit depth of 8. */
86: 	if (color_type == PNG_COLOR_TYPE_GRAY && bit_depth < 8) {
87: 		png_set_expand_gray_1_2_4_to_8(png_ptr);
88: 	} else if (bit_depth == 16) {
89: 		png_set_strip_16(png_ptr);
90: 	}
91: 
92: 	/* Convert transparency chunk to alpha channel. */
93: 	if (png_get_valid(png_ptr, info_ptr, PNG_INFO_tRNS))  {
94: 		png_set_tRNS_to_alpha(png_ptr);
95: 	}
96: 
97: 	/* Convert gray images to RGB. */
98: 	if (color_type == PNG_COLOR_TYPE_GRAY ||
99: 	    color_type == PNG_COLOR_TYPE_GRAY_ALPHA) {
100: 		png_set_gray_to_rgb(png_ptr);
101: 	}
102: 
103: 	/* Ignore alpha for now. */
104: 	if (color_type & PNG_COLOR_MASK_ALPHA) {
105: 		png_set_strip_alpha(png_ptr);
106: 	}
107: 
108: 	/* Get image attributes. */
109: 	width = png_get_image_width(png_ptr, info_ptr);
110: 	height = png_get_image_height(png_ptr, info_ptr);
111: 	bytesPerPixel = 3; /* All images decompress to this size. */
112: 	bytewidth = ADD_PADDING(width * bytesPerPixel); /* Align width. */
113: 
114: 	/* Decompress the PNG row by row. */
115: 	bitmapData = calloc(1, bytewidth * height);
116: 	row = png_malloc(png_ptr, png_get_rowbytes(png_ptr, info_ptr));
117: 	if (bitmapData == NULL || row == NULL) goto bail;
118: 	for (y = 0; y < height; ++y) {
119: 		png_uint_32 x;
120: 		const uint32_t rowOffset = y * bytewidth;
121: 		uint8_t *rowptr = row;
