156: typedef struct _PNGWriteInfo PNGWriteInfo;
157: typedef PNGWriteInfo *PNGWriteInfoRef;
158: 
159: /* Returns pointer to PNGWriteInfo struct containing data ready to be used with
160:  * functions such as png_write_png().
161:  *
162:  * It is the caller's responsibility to destroy() the returned structure with
163:  * destroyPNGWriteInfo(). */
164: static PNGWriteInfoRef createPNGWriteInfo(MMBitmapRef bitmap)
165: {
166: 	PNGWriteInfoRef info = malloc(sizeof(PNGWriteInfo));
167: 	png_uint_32 y;
168: 
169: 	if (info == NULL) return NULL;
170: 	info->png_ptr = NULL;
171: 	info->info_ptr = NULL;
172: 	info->row_pointers = NULL;
173: 
174: 	assert(bitmap != NULL);
175: 
176: 	/* Initialize the write struct. */
177: 	info->png_ptr = png_create_write_struct(PNG_LIBPNG_VER_STRING,
178: 	                                        NULL, NULL, NULL);
179: 	if (info->png_ptr == NULL) goto bail;
180: 
181: 	/* Set up error handling. */
182: 	if (setjmp(png_jmpbuf(info->png_ptr))) {
183: 		png_destroy_write_struct(&(info->png_ptr), &(info->info_ptr));
184: 		goto bail;
185: 	}
186: 
187: 	/* Initialize the info struct. */
188: 	info->info_ptr = png_create_info_struct(info->png_ptr);
189: 	if (info->info_ptr == NULL) {
190: 		png_destroy_write_struct(&(info->png_ptr), NULL);
191: 		goto bail;
192: 	}
193: 
194: 	/* Set image attributes. */
195: 	png_set_IHDR(info->png_ptr,
196: 	             info->info_ptr,
197: 	             (png_uint_32)bitmap->width,
198: 	             (png_uint_32)bitmap->height,
199: 	             8,
200: 	             PNG_COLOR_TYPE_RGB,
201: 	             PNG_INTERLACE_NONE,
202: 	             PNG_COMPRESSION_TYPE_DEFAULT,
203: 	             PNG_FILTER_TYPE_DEFAULT);
204: 
205: 	info->row_count = bitmap->height;
206: 	info->row_pointers = png_malloc(info->png_ptr,
207: 	                                sizeof(png_byte *) * info->row_count);
208: 
209: 	if (bitmap->bytesPerPixel == 3) {
210: 		/* No alpha channel; image data can be copied directly. */
211: 		for (y = 0; y < info->row_count; ++y) {
212: 			info->row_pointers[y] = bitmap->imageBuffer + (bitmap->bytewidth * y);
213: 		}
214: 		info->free_row_pointers = false;
215: 
216: 		/* Convert BGR to RGB if necessary. */
217: 		if (MMRGB_IS_BGR) {
218: 			png_set_bgr(info->png_ptr);
219: 		}
220: 	} else {
221: 		/* Ignore alpha channel; copy image data row by row. */
222: 		const size_t bytesPerPixel = 3;
223: 		const size_t bytewidth = ADD_PADDING(bitmap->width * bytesPerPixel);
224: 
225: 		for (y = 0; y < info->row_count; ++y) {
226: 			png_uint_32 x;
227: 			png_byte *row_ptr = png_malloc(info->png_ptr, bytewidth);
228: 			info->row_pointers[y] = row_ptr;
229: 			for (x = 0; x < bitmap->width; ++x) {
230: 				MMRGBColor *color = MMRGBColorRefAtPoint(bitmap, x, y);
231: 				row_ptr[0] = color->red;
232: 				row_ptr[1] = color->green;
233: 				row_ptr[2] = color->blue;
234: 
235: 				row_ptr += bytesPerPixel;
236: 			}
237: 		}
238: 		info->free_row_pointers = true;
239: 	}
240: 
241: 	png_set_rows(info->png_ptr, info->info_ptr, info->row_pointers);
242: 	return info;
243: 
244: bail:
245: 	if (info != NULL) free(info);
246: 	return NULL;
247: }
