249: /* Free memory in use by |info|. */
250: static void destroyPNGWriteInfo(PNGWriteInfoRef info)
251: {
252: 	assert(info != NULL);
253: 	if (info->row_pointers != NULL) {
254: 		if (info->free_row_pointers) {
255: 			size_t y;
256: 			for (y = 0; y < info->row_count; ++y) {
257: 				free(info->row_pointers[y]);
258: 			}
259: 		}
260: 		png_free(info->png_ptr, info->row_pointers);
261: 	}
262: 
263: 	png_destroy_write_struct(&(info->png_ptr), &(info->info_ptr));
264: 	free(info);
265: }
