294: /* Called each time libpng attempts to write data in createPNGData(). */
295: void png_append_data(png_struct *png_ptr,
296:                      png_byte *new_data,
297:                      png_size_t length)
298: {
299: 	struct io_data *data = png_get_io_ptr(png_ptr);
300: 	data->size += length;
301: 
302: 	/* Allocate or grow buffer. */
303: 	if (data->buffer == NULL) {
304: 		data->allocedSize = data->size;
305: 		data->buffer = png_malloc(png_ptr, data->allocedSize);
306: 		assert(data->buffer != NULL);
307: 	} else if (data->allocedSize < data->size) {
308: 		do {
309: 			/* Double size each time to avoid calls to realloc. */
310: 			data->allocedSize <<= 1;
311: 		} while (data->allocedSize < data->size);
312: 
313: 		data->buffer = realloc(data->buffer, data->allocedSize);
314: 	}
315: 
316: 	/* Copy new bytes to end of buffer. */
317: 	memcpy(data->buffer + data->size - length, new_data, length);
318: }
