330: 	png_set_write_fn(info->png_ptr, &data, &png_append_data, NULL);
331: 	png_write_png(info->png_ptr, info->info_ptr, PNG_TRANSFORM_IDENTITY, NULL);
332: 
333: 	destroyPNGWriteInfo(info);
334: 
335: 	*len = data.size;
336: 	return data.buffer;
337: }

